document.addEventListener('DOMContentLoaded', () => {
    const observationForm = document.getElementById('observationForm');
    const observationsList = document.getElementById('observationsList');
    const observationCountElement = document.getElementById('observation-count');
    const emptyStateMessage = document.getElementById('emptyStateMessage');

    let observations = [];

    /**
     * Renders the current list of observations to the DOM.
     */
    function renderObservations() {
        observationsList.innerHTML = '';

        if (observations.length === 0) {
            emptyStateMessage.style.display = 'block';
            observationCountElement.textContent = 0;
            return;
        }

        emptyStateMessage.style.display = 'none';
        observationCountElement.textContent = observations.length;

        observations.forEach((obs, index) => {
            const card = document.createElement('div');
            card.className = 'observation-card';
            card.innerHTML = `
                <h4>${obs.title}</h4>
                <p><strong>Location:</strong> ${obs.location}</p>
                <p><strong>Note:</strong> ${obs.note}</p>
            `;
            observationsList.appendChild(card);
        });
    }

    /**
     * Handles form submission to add a new observation.
     */
    observationForm.addEventListener('submit', (e) => {
        e.preventDefault();

        const title = document.getElementById('observationTitle').value.trim();
        const location = document.getElementById('observationLocation').value.trim();
        const note = document.getElementById('observationNote').value.trim();

        if (title && location && note) {
            const newObservation = {
                title: title,
                location: location,
                note: note
            };
            observations.push(newObservation);
            renderObservations();

            // Clear the form
            observationForm.reset();
        } else {
            alert('Please fill in all fields.');
        }
    });

    // Initial render (will show empty state)
    renderObservations();
});

